                    Tempo
                  </th>
                  {DIAS.map(dia => (
                    <th key={dia} className="border-b border-r border-slate-100 p-4 text-left font-black text-slate-400 text-[10px] uppercase tracking-widest last:border-r-0">
                      {dia}
                    </th>
                  ))}
