import React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import { useTurma } from '../../contexts/TurmaContext';
import { APP_CONFIG } from '../../config/appConfig';

interface CalendarWidgetProps {
  year: number;
  currentMonth: number;
  onMonthChange: (month: number) => void;
  turmaAtiva: any;
  lancamentos: any[];
  avaliacoes: any[];
  alunos: any[];
  horarioTurma?: any[];
  minMonth?: number;
  maxMonth?: number;
  periodoStart?: string;
  periodoEnd?: string;
}

export default function CalendarWidget({ 
  year, 
  currentMonth,
  onMonthChange,
  turmaAtiva, 
  lancamentos,
  avaliacoes,
  alunos,
  horarioTurma,
  minMonth = 1,
  maxMonth = 11,
  periodoStart,
  periodoEnd
}: CalendarWidgetProps) {

  // Re-calcular datas do período baseadas no Bimestre selecionado (poderiam vir de props, mas mantemos isolado)
  const periodosLetivos = APP_CONFIG.PERIODOS.filter(p => p.id.includes('BIMESTRE')).map(p => {
    const [aiY, aiM, aiD] = p.dataInicio.split('-');
    const start = new Date(Number(aiY), Number(aiM) - 1, Number(aiD));
    const [afY, afM, afD] = p.dataFim.split('-');
    const end = new Date(Number(afY), Number(afM) - 1, Number(afD));
    return { start, end };
  });

  const isDateWithinSchoolYear = (date: Date) => {
    return periodosLetivos.some(p => date >= p.start && date <= p.end);
  };

  const monthNames = [
    'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];

  const handlePrevMonth = () => {
    if (currentMonth > minMonth) onMonthChange(currentMonth - 1);
  };

  const handleNextMonth = () => {
    if (currentMonth < maxMonth) onMonthChange(currentMonth + 1);
  };

  const getDaysArray = () => {
    const daysInMonth = new Date(year, currentMonth + 1, 0).getDate();
    const firstDayOfMonth = new Date(year, currentMonth, 1).getDay();

    const days = [];
    for (let i = 0; i < firstDayOfMonth; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  };

  const calendarDays = getDaysArray();
  const weekDays = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];

  return (
    <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
      {/* Calendar Header */}
      <div className="p-5 flex items-center justify-between border-b border-slate-200">
        <button 
          onClick={handlePrevMonth}
          disabled={currentMonth <= minMonth}
          className="flex items-center gap-1 px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-600 hover:bg-slate-50 transition disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <ChevronLeft className="w-4 h-4" />
          Anterior
        </button>
        <h3 className="text-lg font-semibold text-slate-700">{monthNames[currentMonth].toUpperCase()}</h3>
        <button 
          onClick={handleNextMonth}
          disabled={currentMonth >= maxMonth}
          className="flex items-center gap-1 px-4 py-2 bg-[#0f2851] text-white rounded-xl text-sm font-bold hover:bg-[#1a3a6d] transition disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-[#0f2851]/20"
        >
          Próximo
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 border-l border-slate-200">
        {/* Weekday Headers */}
        {weekDays.map((day) => (
          <div key={day} className="text-center py-4 text-sm font-semibold text-slate-800 border-b border-r border-slate-200">
            {day}
          </div>
        ))}

        {/* Days */}
        {calendarDays.map((day, index) => {
          if (day === null) {
            return <div key={`empty-${index}`} className="min-h-[120px] p-3 border-b border-r border-slate-200 bg-slate-50/50"></div>;
          }

          const dayOfWeek = index % 7;
          const currentDate = new Date(year, currentMonth, day);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          const isWithinSchoolYear = isDateWithinSchoolYear(currentDate);

          // Verifica se o dia pertence EXATAMENTE ao bimestre selecionado
          let isWithinSelectedPeriod = true;
          if (periodoStart && periodoEnd) {
            const [sY, sM, sD] = periodoStart.split('-').map(Number);
            const pStart = new Date(sY, sM - 1, sD);
            const [eY, eM, eD] = periodoEnd.split('-').map(Number);
            const pEnd = new Date(eY, eM - 1, eD);
            isWithinSelectedPeriod = currentDate >= pStart && currentDate <= pEnd;
          }

          const isPastOrToday = currentDate <= today;

          // Agora verificamos se o dia da semana existe no horário cadastrado para esta turma
          const temAulaHoje = horarioTurma?.some(h => Number(h.dia_semana) === dayOfWeek);
          const isDiaDeAula = temAulaHoje && isWithinSchoolYear && isPastOrToday && isWithinSelectedPeriod;

          if (isDiaDeAula) {
            const dayStr = `${year}-${(currentMonth + 1).toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
            const activeTurmaId = String(turmaAtiva?.id).split('||')[0];
            const lancamentosDoDia = lancamentos.filter(l => l.data === dayStr && String(l.turmaId).split('||')[0] === activeTurmaId);

            // Filtramos apenas os tempos que realmente existem no horário para este dia
            const temposValidos = horarioTurma?.filter(h => Number(h.dia_semana) === dayOfWeek).map(h => `${h.tempo_ordem}º TEMPO`) || [];

            const temFrequencia = lancamentosDoDia.some(l => l.tipo === 'frequencia' && temposValidos.includes(l.tempo));
            const temConteudo = lancamentosDoDia.some(l => l.tipo === 'conteudo' && temposValidos.includes(l.tempo));

            // Buscar avaliações no dia
            const avaliacoesDoDia = avaliacoes.filter(av => av.data === dayStr && String(av.turmaId).split('||')[0] === activeTurmaId);
            const temAvaliacao = avaliacoesDoDia.length > 0;

            // Verificar se as avaliações têm notas para todos (ou maioria) dos alunos
            const avaliacoesLancadas = temAvaliacao && avaliacoesDoDia.every(av => {
              const notasDessaAv = alunos.filter(a => a.notas && a.notas[av.id]);
              return notasDessaAv.length > 0; // Se tiver pelo menos uma nota, consideramos "lançada" na legenda visual
            });

            let status: 'none' | 'pending' | 'full' = 'none';
            if (temFrequencia && temConteudo && (!temAvaliacao || avaliacoesLancadas)) status = 'full';
            else if (temFrequencia || temConteudo || temAvaliacao) status = 'pending';

            const fColor = temFrequencia ? 'bg-emerald-500' : 'bg-red-500';
            const cmColor = temConteudo ? 'bg-emerald-500' : 'bg-red-500';
            const aColor = avaliacoesLancadas ? 'bg-emerald-500' : 'bg-red-500';

            const bgColor = status === 'none' ? 'bg-red-100/60' : (status === 'pending' ? 'bg-amber-100/60' : 'bg-emerald-100/60');

            return (
              <Link 
                key={`day-${day}`}
                to={`/frequencia?date=${dayStr}&turmaId=${turmaAtiva?.id}`}
                className={`min-h-[120px] p-3 border-b border-r border-slate-200 flex justify-between ${bgColor} transition-all group relative hover:shadow-md hover:brightness-95`}
              >
                <div className="flex flex-col justify-between">
                  <span className="text-base font-medium text-slate-700">{day}</span>
                </div>
                <div className="flex flex-col gap-1 items-end">
                  <span className={`w-5 h-5 rounded-full ${fColor} text-white flex items-center justify-center text-[10px] font-black shadow-sm`}>F</span>
                  <span className={`w-5 h-5 rounded-full ${cmColor} text-white flex items-center justify-center text-[10px] font-black shadow-sm`}>CM</span>
                  {temAvaliacao && (() => {
                    const temRP = avaliacoesDoDia.some(av => av.tipo?.startsWith('RP'));
                    return (
                      <span className={`${temRP ? 'w-fit px-1.5' : 'w-5'} h-5 rounded-full ${aColor} text-white flex items-center justify-center text-[10px] font-black shadow-sm tracking-tighter`}>
                        {temRP ? 'RP' : 'A'}
                      </span>
                    );
                  })()}
                </div>
              </Link>
            );
          }

          return (
            <div 
              key={`day-${day}`} 
              className="min-h-[120px] p-3 border-b border-r border-slate-200 flex justify-between bg-slate-100/50 opacity-50 cursor-not-allowed"
            >
              <span className="text-base font-medium text-slate-400">{day}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { CheckCircle, XCircle, AlertTriangle, Info, X } from 'lucide-react';

// ============================================================
// Tipos
// ============================================================
type ToastType = 'success' | 'error' | 'warning' | 'info';

interface Toast {
  id: string;
  type: ToastType;
  message: string;
  duration?: number;
}

interface ToastContextType {
  showToast: (message: string, type?: ToastType, duration?: number) => void;
  showSuccess: (message: string) => void;
  showError: (message: string) => void;
  showWarning: (message: string) => void;
  showInfo: (message: string) => void;
}

// ============================================================
// Contexto
// ============================================================
const ToastContext = createContext<ToastContextType | undefined>(undefined);

// ============================================================
// Ícones por tipo
// ============================================================
const ICONS: Record<ToastType, React.ReactNode> = {
  success: <CheckCircle className="w-5 h-5 flex-shrink-0" />,
  error: <XCircle className="w-5 h-5 flex-shrink-0" />,
  warning: <AlertTriangle className="w-5 h-5 flex-shrink-0" />,
  info: <Info className="w-5 h-5 flex-shrink-0" />,
};

// ============================================================
// Estilos por tipo
// ============================================================
const STYLES: Record<ToastType, string> = {
  success: 'bg-emerald-600 text-white border-emerald-700',
  error: 'bg-red-600 text-white border-red-700',
  warning: 'bg-amber-500 text-white border-amber-600',
  info: 'bg-blue-600 text-white border-blue-700',
};

// ============================================================
// Componente individual de Toast
// ============================================================
interface ToastItemProps {
  toast: Toast;
  onRemove: (id: string) => void;
}

const ToastItem: React.FC<ToastItemProps> = ({ toast, onRemove }) => {
  return (
    <div
      className={`
        flex items-start gap-3 px-4 py-3 rounded-xl border shadow-lg
        text-sm font-medium max-w-sm w-full pointer-events-auto
        animate-[slideIn_0.3s_ease-out]
        ${STYLES[toast.type]}
      `}
      role="alert"
    >
      <span className="mt-0.5">{ICONS[toast.type]}</span>
      <p className="flex-1 leading-snug">{toast.message}</p>
      <button
        onClick={() => onRemove(toast.id)}
        className="ml-1 opacity-70 hover:opacity-100 transition-opacity flex-shrink-0 mt-0.5"
        aria-label="Fechar notificação"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

// ============================================================
// Provider
// ============================================================
export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const showToast = useCallback((message: string, type: ToastType = 'info', duration = 4000) => {
    const id = `toast-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const newToast: Toast = { id, type, message, duration };

    setToasts(prev => [...prev.slice(-4), newToast]); // máximo de 5 toasts simultâneos

    if (duration > 0) {
      setTimeout(() => removeToast(id), duration);
    }
  }, [removeToast]);

  const showSuccess = useCallback((message: string) => showToast(message, 'success'), [showToast]);
  const showError   = useCallback((message: string) => showToast(message, 'error', 6000), [showToast]);
  const showWarning = useCallback((message: string) => showToast(message, 'warning'), [showToast]);
  const showInfo    = useCallback((message: string) => showToast(message, 'info'), [showToast]);

  return (
    <ToastContext.Provider value={{ showToast, showSuccess, showError, showWarning, showInfo }}>
      {children}

      {/* Container de Toasts */}
      <div
        className="fixed bottom-6 right-6 z-[9999] flex flex-col gap-2 pointer-events-none"
        aria-live="polite"
        aria-label="Notificações do sistema"
      >
        {toasts.map(toast => (
          <ToastItem key={toast.id} toast={toast} onRemove={removeToast} />
        ))}
      </div>
    </ToastContext.Provider>
  );
}

// ============================================================
// Hook
// ============================================================
export function useToast(): ToastContextType {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast deve ser usado dentro de um ToastProvider');
  }
  return context;
}

import React, { useState } from 'react';
import { RefreshCw, Save } from 'lucide-react';
import Captcha from '../common/Captcha';
import { useCaptcha } from '../../hooks/useCaptcha';

interface AnotacoesTabProps {
  turmaAtiva: any;
  tempoAula: string;
  setTempoAula: (v: string) => void;
  disponiveisTempos: string[];
}

export default function AnotacoesTab({
  turmaAtiva,
  tempoAula,
  setTempoAula,
  disponiveisTempos,
}: AnotacoesTabProps) {
  const [isAddingAnotacao, setIsAddingAnotacao] = useState(false);
  const [showNoRecordsAnotacao, setShowNoRecordsAnotacao] = useState(false);
  const [anotacoes, setAnotacoes] = useState<{ id: string; texto: string; tempo: string; data: string }[]>([]);
  const [textoAnotacao, setTextoAnotacao] = useState('');

  const {
    generatedCaptcha,
    captchaInput,
    setCaptchaInput,
    captchaError,
    generateNewCaptcha,
    validateCaptcha
  } = useCaptcha();

  const handleSave = () => {
    if (validateCaptcha()) {
      if (!textoAnotacao.trim()) {
        alert('Por favor, descreva a anotação.');
        return;
      }

      const novaAnotacao = {
        id: Math.random().toString(36).substr(2, 9),
        texto: textoAnotacao,
        tempo: tempoAula,
        data: new Date().toLocaleDateString('pt-BR')
      };

      setAnotacoes(prev => [novaAnotacao, ...prev]);
      setIsAddingAnotacao(false);
      setTextoAnotacao('');
      setCaptchaInput('');
      generateNewCaptcha();
    } else {
      alert('Código incorreto!');
    }
  };

  return (
    <div className="animate-in fade-in slide-in-from-top-4 duration-300">
      {!isAddingAnotacao ? (
        <>
          <div className="flex items-end gap-4 mb-6">
            <div className="w-64">
              <label className="block text-sm text-slate-600 mb-1">Tempo de aula</label>
              <select
                className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:outline-none focus:border-blue-500"
                value={tempoAula}
                onChange={(e) => setTempoAula(e.target.value)}
              >
                {disponiveisTempos.map((t: string) => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
            </div>
            <button
              onClick={() => setShowNoRecordsAnotacao(true)}
              className="bg-[#eef2ff] text-[#0f2851] border border-blue-100 px-6 py-2 rounded text-sm font-semibold hover:bg-[#e0e7ff] transition h-[38px] shadow-sm active:scale-95"
            >
              Exibir
            </button>
            <button
              onClick={() => setIsAddingAnotacao(true)}
              className="bg-[#eef2ff] text-[#0f2851] border border-blue-100 px-6 py-2 rounded text-sm font-semibold hover:bg-[#e0e7ff] transition h-[38px] flex items-center gap-2 shadow-sm active:scale-95"
            >
              <span className="text-lg leading-none">+</span> Adicionar anotação
            </button>
          </div>

          {showNoRecordsAnotacao && anotacoes.length === 0 && (
            <div className="bg-red-100/80 border border-red-200 text-red-800 px-4 py-3 rounded-lg flex items-center justify-between mb-6">
              <span className="text-sm font-medium">NENHUM REGISTRO ENCONTRADO.</span>
              <button onClick={() => setShowNoRecordsAnotacao(false)} className="text-red-600 hover:text-red-800 transition">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          )}

          {anotacoes.length > 0 && (
            <div className="border border-slate-200 rounded-lg overflow-hidden bg-white">
              <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 border-b border-slate-200 text-slate-600">
                  <tr>
                    <th className="px-4 py-3 font-medium">Data</th>
                    <th className="px-4 py-3 font-medium">Tempo</th>
                    <th className="px-4 py-3 font-medium">Anotação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {anotacoes.map(anot => (
                    <tr key={anot.id} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 text-slate-500">{anot.data}</td>
                      <td className="px-4 py-3 text-slate-500">{anot.tempo}</td>
                      <td className="px-4 py-3 text-slate-700 font-medium">{anot.texto}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      ) : (
        <div className="space-y-6">
          <div className="w-64">
            <label className="block text-sm text-slate-600 mb-1">Tempo de aula:</label>
            <input
              type="text"
              value={tempoAula}
              disabled
              className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 bg-slate-50 cursor-not-allowed"
            />
          </div>

          <div>
            <label className="block text-sm text-slate-600 mb-1">Anotação</label>
            <textarea
              className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:outline-none focus:border-blue-500 min-h-[120px] resize-y bg-slate-50/50"
              value={textoAnotacao}
              onChange={(e) => setTextoAnotacao(e.target.value)}
              placeholder="Descreva aqui sua anotação pedagógica..."
            ></textarea>
          </div>

          <div className="pt-2">
            <Captcha
              generatedCaptcha={generatedCaptcha}
              captchaInput={captchaInput}
              setCaptchaInput={setCaptchaInput}
              captchaError={captchaError}
              generateNewCaptcha={generateNewCaptcha}
              className="mb-6"
            />
             <div className="flex items-center gap-3">
               <button onClick={handleSave} className="flex items-center gap-2 bg-[#eef2ff] text-[#0f2851] border border-blue-100 px-6 py-2 rounded text-sm font-bold hover:bg-[#e0e7ff] transition shadow-sm active:scale-95">
                 <Save className="w-4 h-4" /> Salvar anotação
               </button>
               <button
                 onClick={() => { setIsAddingAnotacao(false); setCaptchaInput(''); generateNewCaptcha(); }}
                 className="bg-white text-slate-600 border border-slate-200 px-6 py-2 rounded text-sm font-medium hover:bg-slate-50 transition"
               >
                 Cancelar
               </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
}

