import React from 'react';
import { X, Calendar as CalendarIcon, Save, Loader2 } from 'lucide-react';
import Captcha from '../../common/Captcha';

interface SegundaChamadaEditorProps {
  selectedAvaliacao: any;
  alunos: any[];
  secondCallRows: Record<string, { selected: boolean, date: string, grade: string }>;
  isSaving: boolean;
  generatedCaptcha: string;
  captchaInput: string;
  captchaError: boolean;
  onSetSecondCallRows: (rows: any) => void;
  onSave: () => void;
  onCancel: () => void;
  onSetCaptchaInput: (val: string) => void;
  onGenerateNewCaptcha: () => void;
}

export default function SegundaChamadaEditor({
  selectedAvaliacao,
  alunos,
  secondCallRows,
  isSaving,
  generatedCaptcha,
  captchaInput,
  captchaError,
  onSetSecondCallRows,
  onSave,
  onCancel,
  onSetCaptchaInput,
  onGenerateNewCaptcha
}: SegundaChamadaEditorProps) {
  if (!selectedAvaliacao) return null;

  const handleSelectAll = (checked: boolean) => {
    const newRows = { ...secondCallRows };
    Object.keys(newRows).forEach(id => newRows[id].selected = checked);
    onSetSecondCallRows(newRows);
  };

  const handleRowChange = (alunoId: string, field: string, value: any) => {
    onSetSecondCallRows((prev: any) => ({
      ...prev,
      [alunoId]: { ...prev[alunoId], [field]: value }
    }));
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500 text-left">
      <div className="px-8 py-6 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
        <div>
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight flex items-center gap-3">
            AVALIAÇÃO DE 2ª CHAMADA
          </h2>
          <p className="text-slate-500 text-sm font-medium mt-1 uppercase tracking-wider">
            VINCULADA A: <span className="text-[#0f2851] font-bold">{selectedAvaliacao.tipo} - {selectedAvaliacao.instrumento}</span>
          </p>
        </div>
        <button onClick={onCancel} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400 hover:text-slate-600">
          <X className="w-6 h-6" />
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-100">
              <th className="px-8 py-4 text-left">
                <input 
                  type="checkbox" 
                  onChange={(e) => handleSelectAll(e.target.checked)}
                  className="rounded border-slate-300 text-[#0f2851] focus:ring-[#0f2851]"
                />
              </th>
              <th className="px-8 py-4 text-left text-xs font-black text-slate-400 uppercase tracking-widest">Nº</th>
              <th className="px-8 py-4 text-left text-xs font-black text-slate-400 uppercase tracking-widest">ALUNO</th>
              <th className="px-8 py-4 text-left text-xs font-black text-slate-400 uppercase tracking-widest">DATA DA AVALIAÇÃO</th>
              <th className="px-8 py-4 text-left text-xs font-black text-slate-400 uppercase tracking-widest">NOTA (0,00 A 10,00)</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {alunos.map((aluno, index) => (
              <tr key={aluno.id} className={`group hover:bg-blue-50/30 transition-colors ${secondCallRows[aluno.id]?.selected ? 'bg-blue-50/20' : ''}`}>
                <td className="px-8 py-4">
                  <input 
                    type="checkbox" 
                    checked={secondCallRows[aluno.id]?.selected}
                    onChange={(e) => handleRowChange(aluno.id, 'selected', e.target.checked)}
                    className="rounded border-slate-300 text-[#0f2851] focus:ring-[#0f2851]"
                  />
                </td>
                <td className="px-8 py-4 text-slate-400 font-bold tabular-nums">{String(index + 1).padStart(2, '0')}</td>
                <td className="px-8 py-4">
                  <div className="flex flex-col">
                    <div className="font-bold text-slate-800 uppercase tracking-tight">{aluno.nome}</div>
                    <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-0.5">MATRÍCULA: {aluno.matricula || '---'}</div>
                  </div>
                </td>
                <td className="px-8 py-4">
                  <div className="relative max-w-[160px]">
                    <input
                      type="date"
                      value={secondCallRows[aluno.id]?.date || ''}
                      disabled={!secondCallRows[aluno.id]?.selected}
                      onChange={(e) => handleRowChange(aluno.id, 'date', e.target.value)}
                      className="w-full px-3 py-2 border-2 border-slate-100 rounded-xl focus:border-blue-200 focus:ring-0 transition-all font-bold text-slate-700 disabled:opacity-50"
                    />
                  </div>
                </td>
                <td className="px-8 py-4">
                  <input
                    type="text"
                    value={secondCallRows[aluno.id]?.grade || ''}
                    disabled={!secondCallRows[aluno.id]?.selected}
                    onChange={(e) => {
                      let val = e.target.value.replace(/\D/g, '');
                      if (val) {
                        let numVal = parseInt(val, 10);
                        if (numVal > 1000) return;
                        val = (numVal / 100).toFixed(2).replace('.', ',');
                      }
                      handleRowChange(aluno.id, 'grade', val);
                    }}
                    placeholder="0,00"
                    className="w-24 text-center py-2 bg-slate-50 border-2 border-slate-100 rounded-xl text-slate-700 font-black focus:border-[#0f2851]/20 focus:bg-white transition-all outline-none disabled:opacity-50"
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="p-8 bg-slate-50 border-t border-slate-100">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6 text-left">
          <div className="w-full md:w-auto">
            <Captcha 
              generatedCaptcha={generatedCaptcha}
              captchaInput={captchaInput}
              setCaptchaInput={onSetCaptchaInput}
              captchaError={captchaError}
              generateNewCaptcha={onGenerateNewCaptcha}
            />
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <button 
              onClick={onCancel}
              className="flex-1 md:flex-none px-8 py-3 bg-white text-slate-600 font-black rounded-2xl border-2 border-slate-100 hover:bg-slate-50 hover:border-slate-200 transition-all uppercase tracking-widest text-xs"
            >
              Cancelar
            </button>
            <button 
              onClick={onSave}
              disabled={isSaving}
              className="flex-1 md:flex-none px-12 py-3 bg-[#0f2851] text-white font-bold rounded-2xl hover:bg-[#1a3a6d] transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-lg shadow-[#0f2851]/30 disabled:opacity-50 active:scale-95"
            >
              {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
              Salvar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
import LoadingFallback from '../components/common/LoadingFallback';

export type UserRole = 'ADMIN' | 'GESTOR' | 'SECRETARIO' | 'PROFESSOR';

export interface User {
  id: string;
  name: string;
  email: string; // Adicionado campo de e-mail real
  role: UserRole;
  title: string;
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  logout: () => Promise<void>;             // Logout Real
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Monitora a sessão real do Supabase
  useEffect(() => {
    const fetchUserData = async (session: any) => {
      if (!session?.user) {
        setUser(null);
        setLoading(false);
        return;
      }

      const { user: authUser } = session;
      const metadata = authUser.user_metadata;

      // Segurança: Prioriza app_metadata (não alterável pelo cliente)
      let role: UserRole = (authUser.app_metadata?.role as UserRole);

      if (!role) {
        // Fallback: busca da tabela de usuários se não estiver no app_metadata
        try {
          const { data: userData, error } = await supabase
            .from('usuarios')
            .select('cargo')
            .eq('id', authUser.id)
            .maybeSingle();

          if (!error && userData) {
            role = (userData.cargo as UserRole) || 'PROFESSOR';
          } else {
            role = 'PROFESSOR';
          }
        } catch {
          role = 'PROFESSOR';
        }
      }

      setUser({
        id: authUser.id,
        name: metadata?.full_name || authUser.email?.split('@')[0] || 'Usuário',
        email: authUser.email || '',
        role: role,
        title: role,
      });
      setLoading(false);
    };

    // Busca a sessão assim que inicializa
    supabase.auth.getSession().then(({ data: { session } }) => {
      fetchUserData(session);
    });

    // Escuta TODOS os eventos de sessão explicitamente para segurança
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      // Evento que encerra a sessão — limpar estado imediatamente
      if (event === 'SIGNED_OUT') {
        setUser(null);
        setLoading(false);
        return;
      }
      // Recuperação de senha — não redirecionar, manter sessão parcial
      if (event === 'PASSWORD_RECOVERY') {
        setLoading(false);
        return;
      }
      // Login, token refresh e outros — recarregar dados do usuário
      fetchUserData(session);
    });

    return () => subscription.unsubscribe();
  }, []);


  // LOGOUT — Revoga sessão no servidor ANTES de limpar o state da UI
  const logout = async () => {
    try {
      await supabase.auth.signOut();
    } finally {
      setUser(null);
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, logout }}>
      {loading ? <LoadingFallback /> : children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { getBimestrePorData, formatarDataParaISO } from '../utils/dateUtils';
import { TurmaService } from '../services/turmaService';
import { useToast } from '../components/common/Toast';

export interface TurmaMetricas {
  frequencia: number;
  objetosMinistrados: number;
  objetosPlanejados: number;
  avaliacoesCadastradas: number;
  avaliacoesPrevistas: number;
  notasLancadas: number;
  notasPrevistas: number;
}

export interface Turma {
  id: string | number;
  ensino: string;
  fase: string;
  componente: string;
  professor: string;
  escola: string;
  turno: string;
  metricas: TurmaMetricas;
  diasDeAula: number[];
  tempos: string[];
}

export interface Lancamento {
  turmaId: string | number;
  data: string;
  tipo: 'frequencia' | 'conteudo';
  tempo: string;
}

export interface Aluno {
  id: string;
  nome: string;
  matricula: string;
  freq: string;
  part: string;
  notas?: Record<string, string>; // ID da avaliação -> valor da nota
}

export interface Avaliacao {
  id: string;
  turmaId: string | number;
  tipo: string;
  data: string;
  instrumento: string;
  objetos: any[];
  bimestre?: string;
  valorMaximo?: number;
  parent_id?: string | number;
}

export interface Conteudo {
  id?: string;
  turmaId: string | number;
  data: string;
  tempo: string;
  objetos: any[];
  habilidades: any[];
  descricao: string;
}

export interface Horario {
  dia_semana: number;
  tempo_ordem: number;
}

interface TurmaContextType {
  turmaAtiva: Turma | null;
  selecionarTurma: (turma: Turma) => void;
  lancamentos: Lancamento[];
  registrarLancamento: (lancamento: Lancamento) => void;
  removerLancamento: (lancamento: Lancamento) => void;
  alunos: Aluno[];
  avaliacoes: Avaliacao[];
  conteudos: Conteudo[];
  horarioTurma: Horario[];
  loading: boolean;
  salvarAvaliacao: (av: Avaliacao) => Promise<string>;
  removerAvaliacao: (id: string) => Promise<void>;
  salvarNotas: (avaliacaoId: string, notas: { alunoId: string, valor: string }[]) => Promise<void>;
  salvarFrequencia: (data: string, tempo: string, alunosFreq: Aluno[]) => Promise<void>;
  salvarConteudo: (cont: Conteudo) => Promise<void>;
  buscarFrequencia: (data: string, tempo: string) => Promise<void>;
  buscarConteudo: (data: string, tempo: string) => Promise<Conteudo | null>;
  removerFrequencia: (data: string, tempo: string) => Promise<void>;
  removerConteudo: (data: string, tempo: string) => Promise<void>;
  carregarFaltasDaData: (data: string) => Promise<void>;
  faltasPorData: Record<string, Set<string>>;
}

const TurmaContext = createContext<TurmaContextType | undefined>(undefined);

export function TurmaProvider({ children }: { children: ReactNode }) {
  const [turmaAtiva, setTurmaAtiva] = useState<Turma | null>(null);
  const [lancamentos, setLancamentos] = useState<Lancamento[]>([]);
  const [alunos, setAlunos] = useState<Aluno[]>([]);
  const [avaliacoes, setAvaliacoes] = useState<Avaliacao[]>([]);
  const [conteudos, setConteudos] = useState<Conteudo[]>([]);
  const [horarioTurma, setHorarioTurma] = useState<Horario[]>([]);
  const [loading, setLoading] = useState(false);
  const [faltasPorData, setFaltasPorData] = useState<Record<string, Set<string>>>({});

  const { showError, showSuccess } = useToast();

  const fetchAvaliacoesInterno = useCallback(async (turmaId: string | number, disciplina: string, contextAlunos: Aluno[], signal?: AbortSignal) => {
    try {
      const { avaliacoes: avsFormatadas, notasData } = await TurmaService.fetchAvaliacoes(turmaId, disciplina);

      if (signal?.aborted) return;

      setAvaliacoes(avsFormatadas);

      if (notasData.length > 0) {
        setAlunos(prevAlunos => {
          const baseAlunos = contextAlunos.length > 0 ? contextAlunos : prevAlunos;
          return baseAlunos.map(aluno => {
            const notasAluno: Record<string, string> = {};
            notasData.filter((n: any) => n.aluno_id.toString() === aluno.id).forEach((n: any) => {
              notasAluno[n.avaliacao_id.toString()] = parseFloat(n.valor).toFixed(2).replace('.', ',');
            });
            return { ...aluno, notas: notasAluno };
          });
        });
      }
    } catch (err) {
      console.error('Erro ao carregar avaliações:', err);
    }
  }, []);

  useEffect(() => {
    const abortController = new AbortController();
    const signal = abortController.signal;

    const carregarDados = async () => {
      if (turmaAtiva && !signal.aborted) {
        setLoading(true);
        // Limpeza antecipada
        setAlunos([]);
        setAvaliacoes([]);
        setLancamentos([]);
        setHorarioTurma([]);
        setConteudos([]);

        try {
          const rawId = turmaAtiva.id.toString().split('||')[0];
          const [ls, hs, alumnosData, conts, freqs] = await Promise.all([
            TurmaService.fetchLancamentos(rawId, turmaAtiva.componente),
            TurmaService.fetchHorario(rawId, turmaAtiva.componente),
            TurmaService.fetchAlunos(rawId),
            TurmaService.fetchAllConteudos(rawId, turmaAtiva.componente),
            TurmaService.fetchAllFrequencias(rawId, turmaAtiva.componente)
          ]);

          if (signal.aborted) return;

          setLancamentos(ls);
          setHorarioTurma(hs);
          setAlunos(alumnosData);
          setConteudos(conts);

          const faltasMap: Record<string, Set<string>> = {};
          freqs.forEach((f: any) => {
            if (f.status === 'F') {
              const normalizedDate = formatarDataParaISO(f.data);
              if (!faltasMap[normalizedDate]) faltasMap[normalizedDate] = new Set();
              faltasMap[normalizedDate].add(f.aluno_id.toString());
            }
          });
          setFaltasPorData(faltasMap);

          await fetchAvaliacoesInterno(rawId, turmaAtiva.componente, alumnosData, signal);
        } catch (err) {
          console.error('Erro ao carregar dados da turma:', err);
          showError('Não foi possível carregar todos os dados desta turma. Verifique sua conexão.');
        } finally {
          if (!signal.aborted) setLoading(false);
        }
      }
    };
    carregarDados();
    return () => { abortController.abort(); };
  }, [turmaAtiva, fetchAvaliacoesInterno, showError]);

  const selecionarTurma = (turma: Turma) => {
    setTurmaAtiva(turma);
  };

  const registrarLancamento = (novo: Lancamento) => {
    setLancamentos(prev => {
      const existe = prev.some(l => 
        String(l.turmaId) === String(novo.turmaId) && 
        l.data === novo.data && 
        l.tipo === novo.tipo && 
        l.tempo === novo.tempo
      );
      if (existe) return prev;
      return [...prev, novo];
    });
  };

  const removerLancamento = (filtro: Lancamento) => {
    setLancamentos(prev => prev.filter(l => 
      !(String(l.turmaId) === String(filtro.turmaId) && 
        l.data === filtro.data && 
        l.tipo === filtro.tipo && 
        l.tempo === filtro.tempo)
    ));
  };

  const salvarAvaliacao = async (av: Avaliacao): Promise<string> => {
    if (!turmaAtiva) return '';
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      const createdId = await TurmaService.salvarAvaliacao(av, rawId, turmaAtiva.componente);
      await fetchAvaliacoesInterno(rawId, turmaAtiva.componente, alunos);
      showSuccess('Avaliação salva com sucesso!');
      return createdId;
    } catch (err) {
      console.error('Erro ao salvar avaliação:', err);
      showError('Não foi possível salvar a avaliação. Verifique sua conexão.');
      return '';
    }
  };

  const removerAvaliacao = async (id: string) => {
    try {
      await TurmaService.removerAvaliacao(id);
      setAvaliacoes(prev => prev.filter(a => a.id !== id));
      showSuccess('Avaliação removida.');
    } catch (err) {
      console.error('Erro ao remover avaliação:', err);
      showError('Não foi possível remover a avaliação.');
    }
  };

  const salvarNotas = async (avaliacaoId: string, notas: { alunoId: string, valor: string }[]) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      await TurmaService.salvarNotas(avaliacaoId, notas);
      await fetchAvaliacoesInterno(rawId, turmaAtiva.componente, alunos);
      showSuccess('Notas salvas com sucesso!');
    } catch (err) {
      console.error('Erro ao salvar notas:', err);
      showError('Ocorreu um erro ao salvar as notas.');
    }
  };

  const salvarFrequencia = async (data: string, tempo: string, alunosFreq: Aluno[]) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      await TurmaService.salvarFrequencia(rawId, turmaAtiva.componente, data, tempo, alunosFreq);

      registrarLancamento({
        turmaId: turmaAtiva.id,
        data,
        tipo: 'frequencia',
        tempo
      });

      await carregarFaltasDaData(data);
      showSuccess('Frequência salva!');
    } catch (err) {
      console.error('Erro ao salvar frequência:', err);
      showError('Erro ao salvar a frequência.');
    }
  };

  const salvarConteudo = async (cont: Conteudo) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      await TurmaService.salvarConteudo(rawId, turmaAtiva.componente, cont);
      registrarLancamento({ turmaId: rawId, data: cont.data, tipo: 'conteudo', tempo: cont.tempo });
      const conts = await TurmaService.fetchAllConteudos(rawId, turmaAtiva.componente);
      setConteudos(conts);
      showSuccess('Conteúdo salvo!');
    } catch (err) {
      console.error('Erro ao salvar conteúdo:', err);
      showError('Erro ao salvar o conteúdo ministrado.');
    }
  };

  const buscarFrequencia = async (data: string, tempo: string) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    const freqData = await TurmaService.buscarFrequencia(rawId, turmaAtiva.componente, data, tempo);

    if (freqData.length > 0) {
      setAlunos(prev => prev.map(aluno => {
        const f = freqData.find(fd => fd.aluno_id === aluno.id);
        if (f) return { ...aluno, freq: f.status, part: f.participacao };
        return aluno;
      }));
      registrarLancamento({ turmaId: rawId, data, tipo: 'frequencia', tempo });
    } else {
      setAlunos(prev => prev.map(aluno => ({ ...aluno, freq: 'P', part: 'Presencial' })));
    }
  };

  const buscarConteudo = async (data: string, tempo: string): Promise<Conteudo | null> => {
    if (!turmaAtiva) return null;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    const contData = await TurmaService.buscarConteudo(rawId, turmaAtiva.componente, data, tempo);
    if (contData) {
      registrarLancamento({ turmaId: rawId, data: contData.data, tipo: 'conteudo', tempo: contData.tempo });
    }
    return contData;
  };

  const removerFrequencia = async (data: string, tempo: string) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      await TurmaService.removerFrequencia(rawId, turmaAtiva.componente, data, tempo);
      removerLancamento({ turmaId: rawId, data, tipo: 'frequencia', tempo });
      setAlunos(prev => prev.map(a => ({ ...a, freq: '', part: 'Presencial' })));
      await carregarFaltasDaData(data);
      showSuccess('Lançamento de frequência removido.');
    } catch (err) {
      showError('Não foi possível remover a frequência.');
    }
  };

  const removerConteudo = async (data: string, tempo: string) => {
    if (!turmaAtiva) return;
    const rawId = turmaAtiva.id.toString().split('||')[0];
    try {
      await TurmaService.removerConteudo(rawId, turmaAtiva.componente, data, tempo);
      removerLancamento({ turmaId: rawId, data, tipo: 'conteudo', tempo });
      const conts = await TurmaService.fetchAllConteudos(rawId, turmaAtiva.componente);
      setConteudos(conts);
      showSuccess('Conteúdo removido.');
    } catch (err) {
      showError('Não foi possível remover o conteúdo.');
    }
  };

  const carregarFaltasDaData = async (data: string) => {
    if (!turmaAtiva) return;
    try {
      const rawId = turmaAtiva.id.toString().split('||')[0];
      const resp = await TurmaService.buscarFrequenciaPorDia(rawId, turmaAtiva.componente, data);
      const idsFaltosos = new Set(resp.filter((f: any) => f.status === 'F').map((f: any) => f.aluno_id.toString()));
      const normalizedDate = formatarDataParaISO(data);
      setFaltasPorData(prev => ({ ...prev, [normalizedDate]: idsFaltosos }));
    } catch (err) {
      console.error('Erro ao carregar faltas:', err);
    }
  };

  return (
    <TurmaContext.Provider value={{ 
      turmaAtiva, selecionarTurma, 
      lancamentos, registrarLancamento, removerLancamento,
      alunos, avaliacoes, conteudos, horarioTurma, loading, 
      salvarAvaliacao, removerAvaliacao, salvarNotas,
      salvarFrequencia, salvarConteudo, buscarFrequencia, buscarConteudo,
      removerFrequencia, removerConteudo, carregarFaltasDaData, faltasPorData
    }}>
      {children}
    </TurmaContext.Provider>
  );
}

export function useTurma() {
  const context = useContext(TurmaContext);
  if (context === undefined) {
    throw new Error('useTurma deve ser usado dentro de um TurmaProvider');
  }
  return context;
}

import { useState, useEffect, useMemo } from 'react';
import { ArrowLeft, GraduationCap, Building2, Clock, BookOpen, Printer, Search } from 'lucide-react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useTurma } from '../contexts/TurmaContext';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../lib/supabase';
import { formatMatricula } from '../utils/formatters';
import TurmaHeaderInfo from '../components/common/TurmaHeaderInfo';
import { APP_CONFIG, getBimestreAtual } from '../config/appConfig';

export default function AparataDetalhes() {
  const { turmaAtiva, alunos, avaliacoes, lancamentos } = useTurma();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const periodoQuery = searchParams.get('periodo');

  const bimestres = APP_CONFIG.PERIODOS.filter(p => p.id.includes('BIMESTRE'));
  const bimestreInfo = bimestres.find(b => b.id === periodoQuery) || getBimestreAtual() || bimestres[0];

  const [search, setSearch] = useState('');
  const [faltasMap, setFaltasMap] = useState<Record<string, number>>({});

  // Buscar histórico de faltas para todos os alunos da turma filtrados pelo período da aparata
  useEffect(() => {
    async function fetchFaltas() {
      if (!turmaAtiva) return;
      try {
        const rawId = turmaAtiva.id.toString().split('||')[0];
        const { data, error } = await supabase
          .from('frequencias')
          .select('aluno_id, status, data')
          .eq('turma_id', rawId)
          .eq('disciplina', turmaAtiva.componente)
          .in('status', ['F', 'FJ']);

        if (error) throw error;

        const map: Record<string, number> = {};

        const pStart = new Date(bimestreInfo.dataInicio + 'T00:00:00');
        const pEnd = new Date(bimestreInfo.dataFim + 'T23:59:59');

        data?.forEach(f => {
          const dataFreq = new Date(f.data + 'T12:00:00'); // Evitar fuso horário
          if (dataFreq >= pStart && dataFreq <= pEnd) {
            map[f.aluno_id] = (map[f.aluno_id] || 0) + 1;
          }
        });
        setFaltasMap(map);
      } catch (err) {
        console.error('Erro ao buscar faltas totais:', err);
      }
    }
    fetchFaltas();
  }, [turmaAtiva, bimestreInfo]);

  // Cálculo de Aulas Dadas (Lançamentos únicos de frequência)
  const aulasDadas = useMemo(() => {
    if (!lancamentos) return 0;
    const uniq = new Set(lancamentos.filter(l => l.tipo === 'frequencia').map(l => `${l.data}|${l.tempo}`));
    return uniq.size;
  }, [lancamentos]);

  // Regra de AVs Planejadas
  const aulasSemanais = (turmaAtiva?.diasDeAula?.length || 0) * (turmaAtiva?.tempos?.length || 0);
  const avsPlanejadas = aulasSemanais <= 3 ? 2 : 3;

  const hoje = new Date();
  const dataHoje = `${hoje.getDate().toString().padStart(2, '0')}/${(hoje.getMonth() + 1).toString().padStart(2, '0')}/${hoje.getFullYear()}`;

  const alunosDetalhados = useMemo(() => {
    const principalAvs = avaliacoes.filter(a => a.tipo.startsWith('AV') && !a.tipo.startsWith('RP'));

    return (alunos || []).map((aluno, index) => {
      // Cálculo Correto da Média (considerando as notas e eventuais recuperações)
      let media = '0,00';
      if (principalAvs.length > 0) {
        let soma = 0;
        let counted = 0;
        principalAvs.forEach(av => {
          const rp = avaliacoes.find(a => a.parent_id?.toString() === av.id?.toString());
          const valAvStr = aluno.notas?.[av.id];
          const valRpStr = rp ? aluno.notas?.[rp.id] : undefined;

          const valAv = valAvStr ? parseFloat(valAvStr.replace(',', '.')) : 0;
          const valRp = valRpStr ? parseFloat(valRpStr.replace(',', '.')) : 0;

          soma += Math.max(isNaN(valAv) ? 0 : valAv, isNaN(valRp) ? 0 : valRp);
          counted++;
        });
        media = counted > 0 ? (soma / counted).toFixed(2).replace('.', ',') : '0,00';
      }

      const faltas = faltasMap[aluno.id] || 0;

      return {
        ...aluno,
        n: index + 1,
        matricula: formatMatricula(aluno.id), 
        media,
        faltas
      };
    });
  }, [alunos, avaliacoes, faltasMap]);

  const alunosFiltrados = alunosDetalhados.filter(a =>
    search === '' ||
    a.nome.toLowerCase().includes(search.toLowerCase()) ||
    a.matricula.includes(search)
  );

  if (!turmaAtiva) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="bg-white p-8 rounded-2xl shadow-lg border border-slate-200 text-center max-w-md w-full">
          <div className="w-16 h-16 bg-[#eef2ff] text-[#0f2851] rounded-full flex items-center justify-center mx-auto mb-4">
            <BookOpen className="w-8 h-8" />
          </div>
          <h2 className="text-xl font-bold text-slate-800 mb-2">Nenhuma turma selecionada</h2>
          <Link to="/diario" className="inline-flex items-center justify-center gap-2 w-full px-6 py-3 bg-[#0f2851] text-white font-bold rounded-xl hover:bg-[#1a3a6d] transition shadow-lg shadow-[#0f2851]/20 mt-4">
            <ArrowLeft className="w-5 h-5" /> Voltar ao Diário
          </Link>
        </div>
      </div>
    );
  }

  const periodo = bimestreInfo.nome;
  const meses = `${new Date(bimestreInfo.dataInicio).toLocaleDateString('pt-BR', { month: 'long' })} - ${new Date(bimestreInfo.dataFim).toLocaleDateString('pt-BR', { month: 'long' })}`;

  const isAparataFechada = localStorage.getItem(`aparata_fechada_${turmaAtiva.id}_${bimestreInfo.id}`) === 'true';

  const handleFecharAparata = () => {
    if (window.confirm(`Tem certeza que deseja FECHAR a aparata do ${periodo}? Não será mais possível fazer lançamentos de frequência, conteúdos e notas neste período.`)) {
      localStorage.setItem(`aparata_fechada_${turmaAtiva.id}_${bimestreInfo.id}`, 'true');
      navigate('/diario');
    }
  };

  const handleReabrirAparata = () => {
    if (window.confirm(`Tem certeza que deseja REABRIR a aparata do ${periodo}? O professor voltará a ter acesso para fazer lançamentos.`)) {
      localStorage.removeItem(`aparata_fechada_${turmaAtiva.id}_${bimestreInfo.id}`);
      navigate('/diario');
    }
  };

  const canReabrir = user?.role === 'GESTOR' || user?.role === 'SECRETARIO' || user?.role === 'ADMIN';

  return (
    <div className="min-h-screen bg-slate-50 relative">
      <div className="relative z-10 p-8 max-w-7xl mx-auto space-y-6">
        <div className="max-w-[1400px] mx-auto p-4 space-y-4">

