import React, { useState } from 'react';
import { ArrowLeft, Calendar as CalendarIcon } from 'lucide-react';
import { Link, useSearchParams } from 'react-router-dom';
import { useTurma } from '../contexts/TurmaContext';
import { APP_CONFIG } from '../config/appConfig';
import { useAuth } from '../contexts/AuthContext';
import { getDayOfWeek } from '../utils/dateUtils';

import FrequenciaTab from '../components/frequencia/FrequenciaTab';
import ObjetoConhecimentoTab from '../components/frequencia/ObjetoConhecimentoTab';
import AnotacoesTab from '../components/frequencia/AnotacoesTab';
import AvaliacoesTab from '../components/frequencia/AvaliacoesTab';
import { getBimestrePorData } from '../utils/dateUtils';

export default function Frequencia() {
  const { turmaAtiva, horarioTurma } = useTurma();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const selectedDateParam = searchParams.get('date') || `${APP_CONFIG.YEAR}-02-06`;

  // ── Shared state ──
  const [activeTab, setActiveTab] = useState('frequencia');
  const [selectedDate, setSelectedDate] = useState(selectedDateParam);

  // Obter tempos válidos para o dia selecionado
  const dow = getDayOfWeek(selectedDate);
  const temposValidosDoDia = React.useMemo(() => {
    if (!turmaAtiva || !horarioTurma) return [];
    return horarioTurma
      .filter(h => Number(h.dia_semana) === dow)
      .sort((a, b) => a.tempo_ordem - b.tempo_ordem)
      .map(h => `${h.tempo_ordem}º TEMPO`);
  }, [horarioTurma, dow, turmaAtiva]);

  // Se não houver aula no dia, mostramos pelo menos o 1º tempo como fallback para não quebrar a UI
  const temposParaMostrar = temposValidosDoDia.length > 0 ? temposValidosDoDia : ['1º TEMPO'];

  const [tempoAula, setTempoAula] = useState(temposParaMostrar[0]);

  // Sincronizar data da URL
  React.useEffect(() => { setSelectedDate(selectedDateParam); }, [selectedDateParam]);

  // Resetar o tempo quando a data mudar (se o tempo atual não for válido para o novo dia)
  React.useEffect(() => {
    if (!temposParaMostrar.includes(tempoAula)) {
      setTempoAula(temposParaMostrar[0]);
    }
  }, [selectedDate, temposParaMostrar]);

  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
  };

  return (
    <div className="min-h-screen bg-slate-50 relative pb-20">
      <div className="relative z-10">
        {/* SubHeader */}
        <div className="bg-blue-50/10 px-8 py-3 flex items-center justify-between border-b border-blue-100/50">
          <div className="flex items-center gap-4">
            <Link to="/diario" className="bg-[#eef2ff] text-[#0f2851] px-4 py-2 rounded-xl flex items-center gap-2 text-sm font-bold border border-blue-100 hover:bg-[#e0e7ff] transition shadow-sm">
              <ArrowLeft className="w-4 h-4" /> Voltar
            </Link>
            <div className="flex items-center gap-3">
              <h2 className="text-[#0f2851] text-lg font-semibold">{turmaAtiva?.ensino} - {turmaAtiva?.fase}</h2>
              <span className="bg-emerald-100 text-emerald-700 text-[10px] font-black px-2 py-0.5 rounded-md border border-emerald-200 uppercase tracking-widest">Ano: {APP_CONFIG.YEAR}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <div className="bg-white border border-blue-100 rounded-lg flex items-center overflow-hidden shadow-sm">
              <span className="px-4 py-1.5 text-sm font-semibold text-[#0f2851]">{selectedDate}</span>
              <button className="bg-[#eef2ff] text-[#0f2851] p-2 hover:bg-[#e0e7ff] transition border-l border-blue-100">
                <CalendarIcon className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        {/* Main Content */}
        <main className="p-8 max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

            {/* Info Cards */}
            <div className="p-6 bg-slate-50/50 border-b border-slate-200">
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[#eef2ff] flex items-center justify-center text-[#0f2851]">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l9-5-9-5-9 5 9 5z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l9-5-9-5-9 5 9 5zm0 0l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14zm-4 6v-7.5l4-2.222" /></svg>
                  </div>
                  <div>
                    <p className="text-xs text-slate-500">Professor</p>
                    <p className="text-sm font-medium text-slate-800">{user?.name?.toUpperCase() || 'NÃO IDENTIFICADO'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[#eef2ff] flex items-center justify-center text-[#0f2851]">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-slate-500">Escola</p>
                    <p className="text-sm font-medium text-slate-800 truncate">{turmaAtiva?.escola}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[#eef2ff] flex items-center justify-center text-[#0f2851]">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-slate-500">Turno</p>
                    <p className="text-sm font-medium text-slate-800 uppercase">{turmaAtiva?.turno}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[#eef2ff] flex items-center justify-center text-[#0f2851]">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-slate-500">Período</p>
                    <p className="text-sm font-medium text-slate-800">{getBimestrePorData(selectedDate) || 'N/D'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[#eef2ff] flex items-center justify-center text-[#0f2851]">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-slate-500">Componente</p>
                    <p className="text-sm font-medium text-slate-800 uppercase truncate">{turmaAtiva?.componente}</p>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex border-b border-slate-200 px-6 bg-white">
              {(['frequencia', 'objeto', 'anotacoes', 'avaliacoes'] as const).map((tab) => {
                const labels: Record<string, string> = { frequencia: 'Frequência', objeto: 'Objeto de Conhecimento', anotacoes: 'Anotações', avaliacoes: 'Avaliações' };
                return (
                  <button key={tab} onClick={() => handleTabChange(tab)}
                    className={`px-6 py-4 text-sm font-bold transition-all relative ${activeTab === tab ? 'text-[#0f2851]' : 'text-slate-400 hover:text-[#0f2851]'}`}>
                    {labels[tab]}
                    {activeTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1 bg-[#0f2851] rounded-t-full" />}
                  </button>
                );
              })}
            </div>

            {/* Content Area */}
            <div className="p-6">
              {activeTab === 'frequencia' && (
                <FrequenciaTab
                  selectedDate={selectedDate}
                  tempoAula={tempoAula}
                  setTempoAula={setTempoAula}
                  disponiveisTempos={temposParaMostrar}
                />
              )}
              {activeTab === 'objeto' && (
                <ObjetoConhecimentoTab
                  turmaAtiva={turmaAtiva}
                  selectedDate={selectedDate}
                  tempoAula={tempoAula}
                  setTempoAula={setTempoAula}
                  disponiveisTempos={temposParaMostrar}
                />
              )}
              {activeTab === 'anotacoes' && (
                <AnotacoesTab
                  turmaAtiva={turmaAtiva}
                  tempoAula={tempoAula}
                  setTempoAula={setTempoAula}
                  disponiveisTempos={temposParaMostrar}
                />
              )}
              {activeTab === 'avaliacoes' && (
                <AvaliacoesTab />
              )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Loader2 } from 'lucide-react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import Background from '../components/Background';
import { useAuth } from '../contexts/AuthContext';
import { APP_CONFIG } from '../config/appConfig';
import { supabase } from '../lib/supabase';
import { translateSupabaseError } from '../utils/supabaseErrors';

export default function Login() {
  const navigate = useNavigate();
  const location = useLocation();
  const successMessage = location.state?.successMessage;
  const { user } = useAuth();

  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Manipulador do form REAL conectado ao Supabase
  const handleRealLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const email = formData.get('email') as string;
    const password = formData.get('password') as string;

    try {
      const { error: signInError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (signInError) throw signInError;

      navigate('/turmas');

    } catch (err: any) {
      setError(translateSupabaseError(err.message));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
      <Background />
      <div className="absolute inset-0 bg-gradient-to-b from-white/80 to-slate-50/40 pointer-events-none" />

      <main className="relative w-full max-w-md z-10">
        <section className="bg-white p-8 md:p-10 shadow-xl border border-slate-100 rounded-2xl">
          <div className="text-center mb-8">
            <div className="flex justify-center mb-6">
              <img src="/logo.png" alt="Logo Diário Digital" className="h-20 w-auto object-contain" />
            </div>
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Diário Digital</h1>
            <p className="text-slate-500 mt-2 text-sm">Entre com suas credenciais de acesso</p>
          </div>

          {successMessage && (
            <div className="mb-6 p-4 bg-emerald-50 text-emerald-700 rounded-xl text-sm font-medium border border-emerald-100 text-center">
              {successMessage}
            </div>
          )}

          {error && (
            <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-xl text-sm font-medium border border-red-100 text-center">
              {error}
            </div>
          )}

          <form onSubmit={handleRealLogin} className="space-y-6">
            <div className="space-y-2">
              <label htmlFor="email" className="block text-sm font-bold text-slate-700 uppercase tracking-wide">E-mail</label>
              <input 
                type="email" 
                id="email" 
                name="email" 
                placeholder="seu@email.com" 
                required 
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#0f2851]/10 focus:border-[#0f2851] transition-all placeholder-slate-400 font-medium bg-slate-50/30"
              />
            </div>

            <div className="space-y-2">
              <label htmlFor="password" className="block text-sm font-bold text-slate-700 uppercase tracking-wide">Senha</label>
              <input 
                type="password" 
                id="password" 
                name="password" 
                placeholder="••••••••" 
                required 
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#0f2851]/10 focus:border-[#0f2851] transition-all placeholder-slate-400 font-medium bg-slate-50/30"
              />
            </div>

            <div className="flex items-center justify-end">
              <div className="text-sm">
                <Link to="/recuperar-senha" className="font-bold text-[#0f2851] hover:underline transition-all">
                  Esqueceu a senha?
                </Link>
              </div>
            </div>

            <div className="pt-2">
              <button 
                type="submit"
                disabled={isLoading}
                className="w-full flex justify-center items-center bg-[#0f2851] hover:bg-[#1a3a6d] disabled:bg-slate-400 text-white text-base font-bold py-4 px-4 rounded-xl shadow-lg shadow-[#0f2851]/20 transition-all active:scale-95"
              >
                {isLoading ? (
                  <><Loader2 className="w-5 h-5 mr-2 animate-spin" /> Entrando...</>
                ) : (
                  'Entrar'
                )}
              </button>
            </div>
          </form>


        </section>

        <footer className="mt-6 text-center text-slate-400 text-xs">
          © {APP_CONFIG.YEAR} Diário Digital. Todos os direitos reservados.
        </footer>
      </main>
    </div>
  );
}

